package com.smritisathi.app.games;
import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import com.smritisathi.app.core.*;
public class PatternRecognitionActivity extends GameBase {String[][] seq={{"☀","☁","☀"},{"★","☾","★"},{"☁","★","☁"},{"☾","☀","☾"},{"☀","★","☀"}};String[] correct={"☁","☾","★","☀","★"};String[][] opts={{"☁","★","☾"},{"☀","☾","☁"},{"☀","★","☾"},{"☁","☀","★"},{"☾","★","☁"}};int round=0,total=0;long sumRt=0,rs;TextView seqText,roundText;LinearLayout options;@Override public void onCreate(Bundle b){super.onCreate(b);gameHeader("Pattern Recognition","What comes next in the sequence?");roundText=UI.text(this,"");seqText=UI.text(this,"");root.addView(roundText);root.addView(seqText);options=new LinearLayout(this);root.addView(options);showRound();}void showRound(){roundText.setText("Round "+(round+1)+" of 5");seqText.setText(seq[round][0]+"   "+seq[round][1]+"   "+seq[round][2]+"   ?");options.removeAllViews();ArrayList<String> o=new ArrayList<>(Arrays.asList(opts[round]));Collections.shuffle(o);rs=System.currentTimeMillis();for(String x:o){Button b=UI.button(this,x);options.addView(b);b.setOnClickListener(v->{long rt=System.currentTimeMillis()-rs;sumRt+=rt;if(x.equals(correct[round]))total++;b.setEnabled(false);new Handler().postDelayed(()->{round++;if(round<5)showRound();else finishGame();},1000);});}}void finishGame(){int acc=Math.round(total/5f*100);int avg=Math.round(sumRt/5f);int dur=Math.round(sumRt/1000f);int score=Math.round((float)(acc*.85+Math.max(0,100-avg/100f)*.15));complete("patternRecognition",score,acc,avg,dur);}}
